import {configurationPage} from './config-page.js';
import {installScope} from './scope.js';
import {projects,state,save,reset,task,prompt,connectionFor,libraryLabels} from './mock.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pages={scope:['▧','完整能力与配置'],home:['◈','总览'],plugins:['▦','能力与插件'],config:['⚙','工程配置'],clients:['⌘','Agent 客户端'],connections:['⇄','MCP 与连接'],knowledge:['▤','知识与向量'],manual:['▧','使用手册'],tasks:['◷','任务与恢复'],modules:['⊞','模块']};
let liveCatalog;try{const r=await fetch('/catalog.json');if(!r.ok)throw Error();liveCatalog=await r.json()}catch{liveCatalog={plugins:[],basePlugins:[],groups:[],unavailable:[],error:true}}
let group='all';
const alias=n=>({'coding-iris-plugin':'iris','bos-plugin':'bos','imedical-ui':'ui'}[n]||n);
const meta=k=>liveCatalog.plugins.find(p=>alias(p.name)===k);
const isBase=k=>liveCatalog.basePlugins.includes(meta(k)?.name);
function dependencies(k,seen=new Set()){if(seen.has(k))return [...seen];seen.add(k);for(const n of meta(k)?.dependencies||[])dependencies(alias(n),seen);return [...seen]}
let id='clinic',page='home',filter='',manual=0;const docs=['usage-manual.md','connection-configuration.md','plugin-deployment.md'];const docNames=['团队使用手册','连接配置与排查','插件按需部署'];try{const r=await fetch('/manuals.json');if(r.ok){for(const d of await r.json()){if(!docs.includes(d.file)){docs.push(d.file);docNames.push(d.title)}}}}catch{}let docText='';
const btn=(text,action,primary=false,extra='')=>`<button ${primary?'class="primary"':''} data-action="${action}" ${extra}>${text}</button>`;
const link=(text,target)=>`<a href="#/${id}/${target}">${text} →</a>`;
const badge=(text,kind='')=>`<span class="pill ${kind}">${esc(text)}</span>`;
const field=(label,name,value,type='text',help='')=>`<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${type==='number'?'min="1" max="65535"':''} required>${help?`<small>${help}</small>`:''}</div>`;
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000)}
function modal(title,body,actions=''){const d=$('#dialog');d.innerHTML=`<h2>${title}</h2>${body}<div class="actions">${actions}${btn('关闭','close')}</div>`;d.showModal()}
function go(p,project=id){location.hash=`/${project}/${p}`}
function heading(title,desc,action=''){return `<div class="page-heading"><div><h2>${title}</h2><p>${desc}</p></div>${action}</div>`}
function row(title,desc,right=''){return `<div class="row"><div><h3>${title}</h3><p>${desc}</p></div><div class="actions">${right}</div></div>`}
function currentName(){return state(id).name||projects[id].name}
function nextTask(){return state(id).tasks.find(t=>t.status!=='已完成')}
function home(){const s=state(id),pending=nextTask();if(!s.installed)return wizard();return `${heading('项目总览','把注意力留给开发，框架准备交给工作台。',btn('检查当前状态','check'))}<section class="hero"><div><h2>${pending?'接续上一次工作':'准备就绪，从这里开始'}</h2><p>${pending?esc(pending.title)+' · '+esc(pending.status):'连接、能力和客户端已归集到当前工程。选择目标，工作台会带你完成必要步骤。'}</p>${btn(pending?'继续任务':'开始开发',pending?'tasks':'start',true)} <span class="muted">${s.client} · ${s.mode==='offline'?'离线开发':'连接开发'}</span></div><div class="hero-art" aria-hidden="true"><i></i><i></i><i></i></div></section><div class="grid"><article class="card"><h3>需要新的开发能力？</h3><p>按用途选择能力，依赖和接入步骤一起处理。</p><div class="actions">${link('管理能力','plugins')}</div></article><article class="card"><h3>连接只配置一次</h3><p>查看连接来源、引用服务与当前验证状态。</p><div class="actions">${link('查看连接','connections')}</div></article><article class="card"><h3>${projects[id].parent?'共享框架来自 Root':'让框架保持可用'}</h3><p>${projects[id].parent?'更新由共享工作区协调，本模块配置独立保存。':'更新前查看影响，保留现有配置与定制内容。'}</p><div class="actions">${btn('预览更新','update')}</div></article></div><div class="grid two"><section><div class="section-title"><h3>当前工程</h3>${link('编辑配置','config')}</div><div class="panel">${row('IRIS 开发',s.plugins.iris?'已启用 · 配置来自当前工程':'未启用',badge(s.plugins.iris?'可使用':'待接入',s.plugins.iris?'good':'warn'))}${row(s.client,'规则与技能入口已生成',badge(s.clients[s.client]||'未接入'))}${row('框架版本',s.updated?'已更新到演示目标版本':'演示基线 · Node 24.22.3',badge('模拟状态'))}</div></section><section><div class="section-title"><h3>最近任务</h3>${link('查看全部','tasks')}</div><div class="panel">${s.tasks.length?s.tasks.slice(0,3).map(t=>row(esc(t.title),esc(t.type),badge(t.status,t.status==='已完成'?'good':'warn'))).join(''):'<div class="empty">还没有操作记录<br><small>从一个目标开始，过程会保存在这里。</small></div>'}</div></section></div>`}
function wizard(){const s=state(id),n=s.wizard;const titles=['环境检查','用途与客户端','部署摘要','必要配置','接续与验证'];let body='';if(n===0)body=`<h3>已有业务文件，无需重新建工程</h3><p class="muted">发现 AGENTS.md、业务源码与编辑器配置。接入时保留这些内容。</p>${row('Node 24.22.3 / Git',s.environment?'演示环境已准备':'需要通过已有安装助手准备',badge(s.environment?'可用':'缺项',s.environment?'good':'warn'))}<div class="actions">${btn('查看安装指引','environment')}${btn('模拟已安装并重新检查','env-done',true)}</div>`;if(n===1)body=`<form id="purpose"><div class="field"><label for="purpose-select">这次准备做什么？</label><select id="purpose-select"><option>IRIS 开发</option><option>界面改造</option><option>BOS 需求协作</option></select></div><div class="field"><label for="client-select">使用的 Agent 客户端</label><select id="client-select" name="client"><option>Codex</option><option>Claude Code</option><option>其他客户端</option></select></div><p class="note">自动包含基础上下文能力；领域配置按目标收集，不要求手工处理依赖。</p><button class="primary">查看部署摘要</button></form>`;if(n===2)body=`<h3>为 ${esc(currentName())} 接入 ${esc(s.purpose||'IRIS 开发')}</h3>${row('部署来源','演示能力包 · 不执行下载或安装',badge('模拟'))}${row('保留','已有 AGENTS.md、源码、MCP 自定义字段')}${row('客户端',esc(s.client))}${btn('模拟部署并继续','deploy',true)}`;if(n===3)body=configForm(true);if(n===4)body=`<h3>本地步骤已准备，接下来补全工程事实</h3><p class="note">工程探索需要 Agent 判断。你可以模拟宿主接入，也可以复制请求到已有客户端。</p>${btn('创建初始化接续任务','init-task',true)}`;return `${heading('接入当前工程','从已有业务工程开始，保留你已完成的配置。')}<div class="steps">${titles.map((t,i)=>`<div class="step ${i===n?'current':''}">${i+1} ${t}</div>`).join('')}</div><section class="panel form">${body}${n>0&&n<3?`<div class="actions">${btn('上一步','wizard-back')}</div>`:''}${n===0&&s.environment?`<div class="actions">${btn('选择用途','wizard-next',true)}</div>`:''}</section>`}
function configForm(wizardMode=false){const s=state(id),d=s.draft;return `<form id="config-form" data-wizard="${wizardMode}">${d?`<p class="note">有未应用草稿：候选端口 ${d.port}；当前值 ${connectionFor(s).port}。${btn('恢复草稿到表单','restore-draft')}</p>`:''}${field('项目显示名称','name',currentName())}<div class="field"><label for="mode">开发方式</label><select id="mode" name="mode"><option value="connected" ${s.mode==='connected'?'selected':''}>连接开发</option><option value="offline" ${s.mode==='offline'?'selected':''}>离线开发</option></select><small>只影响当前工程；已有连接保持，不因切换方式删除。</small></div>${field('演示连接地址','host',connectionFor(s).host,'text','虚构地址；不会发起请求，请勿输入真实凭据。')}${field('Web 端口','port',connectionFor(s).port,'number')}<details><summary>高级与来源信息</summary><p class="note">来源：当前 ContextRoot 的配置文件。真实产品通过 owner 服务合并，本原型只保存浏览器演示数据。</p></details><button class="primary">${wizardMode?'保存演示配置并继续':'预览修改'}</button></form>`}
const catalog=liveCatalog.plugins.map(p=>[alias(p.name),p.displayName||p.name,p.description,p.name]);
function plugins(){const s=state(id),business=catalog.filter(x=>!isBase(x[0])),shown=business.filter(x=>(group==='all'||liveCatalog.groups.find(g=>g.id===group)?.plugins.includes(x[3]))&&x.join(' ').toLowerCase().includes(filter.toLowerCase()));return `${heading('能力与插件','仓库完整能力目录 · 按当前工程需要接入，不必一次装齐。')}<div class="note">目录与版本实时读取当前源仓 manifest；项目启用/安装状态仍是演示数据。基础插件随框架维护，不参与启停。</div>${liveCatalog.error?'<div class="note warn">无法读取仓库目录，已停止提供插件操作。请重启预览服务。</div>':''}<div class="actions" style="margin-bottom:20px"><input class="search" id="plugin-search" placeholder="搜索用途、名称或插件标识" aria-label="搜索插件" value="${esc(filter)}"><select id="plugin-group" aria-label="插件分类"><option value="all">全部业务能力 (${business.length})</option>${liveCatalog.groups.map(g=>`<option value="${g.id}" ${group===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}</select><span class="muted">显示 ${shown.length} 项</span></div><div class="grid">${shown.map(([key,name,desc,owner])=>{const m=meta(key),enabled=s.plugins[key],available=s.available?.includes(key);return `<article class="card"><div class="actions">${badge(enabled?'已启用':available?'已安装待配置':'未安装',enabled?'good':available?'warn':'')}${badge('v'+m.version)}</div><h3 style="margin:18px 0 10px">${esc(name)}</h3><p>${esc(desc)}</p><small>${esc(owner)}</small><div class="actions">${btn(enabled?'停用':available?'继续配置':'接入此能力',`plugin:${key}`,!enabled)}${btn('依赖与来源',`dependency:${key}`)}</div></article>`}).join('')||'<div class="empty">没有匹配的插件，请调整分类或关键词。</div>'}</div><details class="panel" style="margin-top:24px"><summary>框架内置 · ${liveCatalog.basePlugins.length} 项（不参与启停）</summary>${catalog.filter(x=>isBase(x[0])).map(([k,n,d,o])=>row(esc(n),esc(o)+' · v'+meta(k).version,badge('框架固定保留','good'))).join('')}</details>${liveCatalog.unavailable.length?`<details class="panel" style="margin-top:16px"><summary>暂不可用目录 · ${liveCatalog.unavailable.length} 项</summary>${liveCatalog.unavailable.map(n=>row(esc(n),'没有插件 manifest，不提供启用操作',badge('待治理','warn'))).join('')}</details>`:''}`}
function legacyConfig(){const s=state(id);return `${heading('工程配置','明确来源和影响范围，已有有效值优先保留。')}${s.legacy?'<div class="note warn">当前演示旧框架缺少配置写接口。可以查看现状、预览升级，或交给 Agent 定向处理。</div>':''}${s.custom?'<div class="note warn">发现自定义配置，此域仅供读取，已有内容不会重写。</div>':''}<section class="panel form">${s.legacy||s.custom?row('现有连接',`${esc(connectionFor(s).host)}:${connectionFor(s).port}`,btn('生成处理请求','start')):configForm()}</section>`}
function clients(){const s=state(id);return `${heading('Agent 客户端','入口适配与任务调用是两件事，各自检查、各自呈现。')}<div class="note">下列调用能力仅用于演示交互，不表示相应宿主已经实现集成。</div><div class="grid">${['Codex','Claude Code','OpenCode','CodeBuddy','WorkBuddy','Hermes','其他客户端'].map((c,i)=>`<article class="card"><span class="task-type">${i===0?'模拟任务调用':i===1?'打开与提示词':'提示词接续'}</span><h2 style="margin:12px 0">${c}</h2><p>${esc(s.clients[c]||'尚未生成工程入口')}</p><div class="status-line">规则 · Skills · Agents · MCP</div><div class="actions">${btn('适配工程入口',`adapt:${c}`,true)}${btn('检查发现',`discover:${c}`)}${btn('开始任务',`client-task:${c}`)}</div></article>`).join('')}</div><section class="panel" style="margin-top:22px">${row('用户级设置','可能影响其他工程，修改前单独查看范围',btn('查看影响','user-scope'))}</section>`}
function connections(){const s=state(id);return `${heading('MCP 与连接','连接档案被多个服务引用，避免重复填写。',btn('修改连接','config'))}<div class="grid two"><section class="panel"><h3>当前开发库 ${libraryLabels[s.activeLibrary]}</h3>${row('地址',`${esc(connectionFor(s).host)}:${connectionFor(s).port}`)}${row('凭据',connectionFor(s).secret?'已设置（虚构）':'未设置',btn('凭据操作','secret'))}${row('作用域',projects[id].parent?'当前模块，不影响其他模块':'当前工程')}${row('连接验证',s.tested?'模拟已连到'+libraryLabels[s.activeLibrary]:s.needsReconnect?'客户端待重连核验':'未测试',btn('模拟连接检查','test-connection',true))}</section><section class="panel"><h3>MCP 服务</h3>${row('iris-agentic-dev','引用：'+libraryLabels[s.activeLibrary],badge('配置存在','good'))}${row('程序存在性','模拟文件检查通过',badge('已生成'))}${row('宿主加载','仍需在客户端验证',btn('前往客户端','clients'))}<p class="note">工具发现不等于认证成功；本原型不会启动 MCP 进程。</p></section></div>`}
function knowledge(){const s=state(id);return `${heading('知识与向量','先本地检索，需要时再构建向量。')}<form id="knowledge-search" class="actions"><input class="search" name="query" placeholder="搜索连接、插件或接入方法" aria-label="知识检索"><button>检索</button></form><div id="results"></div><div class="grid two"><section class="panel"><h3>${id==='root'?'共享知识':'当前工程资料'}</h3>${docNames.map((n,i)=>row(n,`docs/guides/${docs[i]}`,btn('查看来源',`doc:${i}`))).join('')}</section><section class="panel"><h3>向量索引</h3><p class="muted">演示资料 · 模拟提供方 · 不外发内容</p><div class="metric">${s.vector}% <small>构建完成</small></div><div class="progress"><span style="width:${s.vector}%"></span></div>${badge(s.vector===100?'模拟索引完整':s.vector?'已中断，可续建':'尚未构建',s.vector===100?'good':'warn')}<div class="actions" style="margin-top:22px">${btn('预览构建','vector-preview',true)}${s.vector>0&&s.vector<100?btn('继续构建','vector-resume'):''}${s.vector===100?btn('查看导出摘要','vector-export'):''}</div></section></div>`}
function formatManual(text){const lines=text.split('\n'),inline=v=>esc(v).replace(/`([^`]+)`/g,'<code>$1</code>').replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');let out='',code=false;for(let i=0;i<lines.length;i++){const line=lines[i];if(line.startsWith('```')){code=!code;out+=code?'<pre><code>':'</code></pre>';continue}if(code){out+=esc(line)+'\n';continue}if(line.trim().startsWith('|')){const rows=[];while(i<lines.length&&lines[i].trim().startsWith('|')){const cells=lines[i].trim().replace(/^\||\|$/g,'').split('|');if(!cells.every(c=>/^[:\s-]+$/.test(c)))rows.push(cells);i++}i--;out+='<div class="table-wrap"><table>'+rows.map((r,j)=>'<tr>'+r.map(c=>`<${j?'td':'th'}>${inline(c)}</${j?'td':'th'}>`).join('')+'</tr>').join('')+'</table></div>';continue}const h=line.match(/^(#{1,6}) (.*)/);if(h){out+=`<h${Math.min(h[1].length+1,4)}>${inline(h[2])}</h${Math.min(h[1].length+1,4)}>`;continue}if(line.trim())out+=`<p>${inline(line)}</p>`}return out+(code?'</code></pre>':'')}
function manuals(){return `${heading('使用手册','沿用框架原文，从说明直接进入操作。')}<input id="manual-search" class="search" placeholder="搜索手册标题或当前正文" aria-label="搜索手册"><div class="split"><div class="tab-list">${docNames.map((n,i)=>btn(n,`doc:${i}`,i===manual)).join('')}<div id="manual-match" class="muted"></div></div><article class="panel manual"><small>来源：docs/guides/${docs[manual]} · 本地只读</small><div class="actions" style="margin:16px 0">${btn('进入相关配置',manual===2?'plugins':'connections',true)}${btn('生成相关请求','manual-task')}</div><div class="manual-body">${formatManual(docText||'正在读取本地原文…')}</div></article></div>`}
async function loadDoc(){const wanted=manual;try{const r=await fetch(`/manual/${docs[wanted]}`);if(!r.ok)throw Error();const text=await r.text();if(page==='manual'&&wanted===manual){docText=text;render()}}catch{docText='本地手册未能读取，请使用 Node 预览入口启动。';render()}}
function modules(){return `${heading('模块','共享框架统一维护，业务配置各自独立。',btn('预览共享更新','update',true))}<div class="grid">${['dental','nursing'].map(k=>`<article class="card"><span class="task-type">OVERLAY MODULE</span><h2 style="margin:12px 0">${esc(state(k).name||projects[k].name)}</h2><p>${projects[k].path}</p><div class="actions">${badge(state(k).updated?'已刷新':'待统一更新',state(k).updated?'good':'')}<a href="#/${k}/home">进入模块 →</a></div></article>`).join('')}</div><p class="note">停用模块插件不会删除共享物料。共享裁剪需要完整成员信息，本原型只演示更新与失败模块重试。</p>`}
function tasks(){const s=state(id);return `${heading('任务与恢复','工具、Agent 与人工各做擅长的部分，完成后统一检查。',btn('新建演示任务','start'))}<section class="panel">${s.tasks.length?s.tasks.map(t=>row(esc(t.title),`${esc(t.type)} · ${t.id.slice(0,8)}`,badge(t.status,t.status==='已完成'?'good':'warn')+btn('查看与接续',`task:${t.id}`))).join(''):'<div class="empty">暂无任务。开始开发或配置能力后，任务会出现在这里。</div>'}</section>`}
const scope=installScope({esc,btn,modal,currentName});
const refinedConfig=configurationPage({state,save,projects,esc,getId:()=>id,render,currentName});
function config(){return state(id).legacy||state(id).custom?legacyConfig():refinedConfig()}
function render(){document.body.classList.toggle("config-sample",page==="config");const p=projects[id],s=state(id);const domainLinks={connections:['iris','web','bos','embedding','mcp'],clients:['hosts'],knowledge:['sources','embedding','vectors'],tasks:['recovery','backup'],home:['install','update']};document.title=`${s.name||p.name} · .agents`;$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span>·</span>agents</div><div class="nav-label">工程工作台</div><nav class="nav">${Object.entries(pages).filter(([k])=>k!=='modules'||id==='root').map(([k,[icon,name]])=>`<a class="${page===k?'active':''}" ${page===k?'aria-current="page"':''} href="#/${id}/${k}">${name}</a>`).join('')}</nav><div class="side-bottom">本地运行 · 数据按工程隔离<br>所有执行均为模拟${btn('演示控制','demo')}</div></aside><div class="main"><header class="top"><div><h1>${esc(currentName())}</h1><div class="top-meta">${badge(p.kind)}<small>${p.path}</small>${p.parent?`<a href="#/root/modules">所属：医疗研发工作区 ↗</a>`:''}</div></div><div class="actions">${badge('原型演示','warn')}${badge(s.client)}${btn('帮助','help')}</div></header><main class="content">${domainLinks[page]?`<div class="actions scope-shortcuts">${domainLinks[page].map(k=>btn(({identity:"接管配置",iris:"IRIS 配置",web:"Web / SFTP",bos:"BOS 凭据",embedding:"知识 Key",profiles:"领域配置",mcp:"MCP 注册",hosts:"适配范围",sources:"资料来源",vectors:"索引管理",recovery:"冲突与恢复",backup:"备份与迁移",install:"首次接入",update:"更新与离线包"})[k],`scope-open:${k}`)).join('')}</div>`:''}${({scope,home,plugins,config,clients,connections,knowledge,manual:manuals,tasks,modules}[page]||home)()}<div class="footer">.agents 工作台 / 交互原型 · 只保存本浏览器的虚构演示数据，不操作真实工程</div></main></div></div>`}
function route(){const parts=location.hash.replace(/^#\//,'').split('/');id=projects[parts[0]]?parts[0]:'clinic';page=pages[parts[1]]?parts[1]:'home';if(page==='modules'&&id!=='root')page='home';filter='';if($('#dialog').open)$('#dialog').close();render();if(page==='manual')loadDoc()}
function findTask(tid){return state(id).tasks.find(t=>t.id===tid)}
function showTask(t){modal(esc(t.title),`<div class="actions">${badge(t.type)}${badge(t.status,t.status==='已完成'?'good':'warn')}</div><div class="steps">${t.steps.map((s,i)=>`<span class="step ${t.status==='已完成'||i===0?'current':''}">${s}</span>`).join('')}</div>${t.type==='共享更新'?`<p class="note">共享能力包已模拟更新一次。模块刷新分别记录，不回滚成功模块。</p>${row(esc(state('dental').name||projects.dental.name),'刷新成功',badge('完成','good'))}${row(esc(state('nursing').name||projects.nursing.name),state('nursing').updated?'重试成功':'刷新失败：演示冲突',state('nursing').updated?badge('完成','good'):btn('仅重试此模块',`retry:${t.id}`,true))}`:t.type==='工具执行'?`<p>当前状态：${esc(t.status)}</p>`:`<p class="note">${t.type==='人工操作'?'请在客户端完成信任或重载，然后返回检查。':'需要核对代码与工程语义。以下为完整交接请求，不包含凭据。'}</p><textarea aria-label="交接提示词" readonly>${esc(prompt(id,t))}</textarea>${t.status==='待补充回答'?`<div class="field"><label for="answer">Agent 需要确认：本次范围是什么？</label><input id="answer" placeholder="例如：仅核对当前模块的工程配置"></div>`:''}<div class="actions" ${t.status==='已完成'?'hidden':''}>${t.type==='Agent 执行'?btn('模拟派发',`dispatch:${t.id}`,true):''}${btn('复制提示词',`copy:${t.id}`)}${t.status==='待补充回答'?btn('提交回答',`answer:${t.id}`,true):''}${btn('模拟宿主/人工已返回',`returned:${t.id}`)}${btn('重新检查结果',`verify:${t.id}`,true)}</div><small>复制、派发或标记返回均不等于完成。检查结果独立显示。</small>`}`)}
function newAgent(title='核对工程配置与开发准备',type){const s=state(id);const t=task(id,title,type||(s.client==='Codex'?'Agent 执行':'提示词交接'),'待接续');go('tasks');setTimeout(()=>showTask(t),50)}
async function action(a){const s=state(id),[op,arg]=a.split(':');if(pages[a]){$('#dialog').close();go(a);return}if(op==='restore-draft'){const d=s.draft;for(const k of ['name','host','port','mode'])document.getElementById(k).value=d[k];toast('草稿已回填，请核对当前来源后重新预览');return}if(op==='close'){$('#dialog').close();return}
if(op==='demo'){modal('演示控制',`<p class="muted">此面板仅用于评审，不是正式产品的项目管理入口。</p><div class="actions" style="margin:18px 0">${Object.entries(projects).map(([k,p])=>btn(p.name,`scene:${k}`)).join('')}</div><h3>当前工程异常场景</h3><div class="actions">${btn('旧框架接口缺失','legacy')}${btn('自定义域只读','custom')}${btn('下次保存发生冲突','conflict')}</div>`,btn('重置全部演示','reset'));return}
if(op==='scene'){$('#dialog').close();go('home',arg);return}if(op==='reset'){reset();$('#dialog').close();go('home','clinic');render();toast('演示状态已重置');return}
if(['legacy','custom','conflict'].includes(op)){s[op]=!s[op];save();$('#dialog').close();go('config');render();toast('演示场景已切换');return}
if(op==='help'){modal('围绕目标开始工作','<p>首页给出下一步；能力页负责补装，配置页负责已知字段，Agent 负责工程探索。遇到失败可在任务页接续。</p><p class="note">本原型的按钮不会启动程序或访问远端。请使用演示控制查看新工程及 Overlay。</p>',btn('阅读使用手册','manual'));return}
if(op==='check'){toast('模拟检查完成：本地入口存在，真实宿主与连接仍待验证');return}
if(op==='environment'){modal('准备基础环境','<p>正式产品引导使用 ai-dev-offline 安装助手部署 Node 24.22.3 与 Git，再返回重新检查。本原型不启动安装器。</p>',btn('模拟环境已准备','env-done',true));return}
if(op==='env-done'){s.environment=true;save();$('#dialog').close();render();toast('演示环境检查通过');return}if(op==='wizard-next'||op==='wizard-back'){s.wizard+=op==='wizard-next'?1:-1;save();render();return}
if(op==='deploy'){const t=task(id,'首次部署与入口准备','工具执行','执行中');s.deployTask=t.id;save();modal('正在模拟部署','<p>保留已有配置 → 准备能力 → 生成客户端入口</p>');const owner=id;setTimeout(()=>{const x=state(owner);x.tasks.find(q=>q.id===t.id).status='已完成';x.wizard=3;save();if(id===owner){$('#dialog').close();render()}},650);return}
if(op==='init-task'){s.installed=true;s.plugins.iris=true;s.clients[s.client]='入口已生成';save();newAgent('补全首次接入的工程事实');return}
if(op==='start'){modal('开始一项工作','<p>选择需要工作台协助完成的目标。</p><div class="actions">'+btn('接入 IRIS 开发','init-task',true)+btn('诊断工程问题','diagnose')+btn('模拟人工重载','human')+'</div>');return}
if(op==='diagnose'||op==='human'){newAgent(op==='human'?'客户端信任与重载':'诊断当前工程接入问题',op==='human'?'人工操作':undefined);return}
if(op==='dependency'){const m=meta(arg);modal('能力依赖与来源',`<h3>${esc(m.displayName||m.name)} · ${esc(m.version)}</h3><p>${esc(m.description)}</p><p class="note">必需依赖：${m.dependencies.length?m.dependencies.map(esc).join('、'):'无'}。${projects[id].parent?'物料由共享 CapabilityRoot 保管；启用只影响当前模块。':'安装及启用归当前工程。'}</p><small>来源：plugins/${esc(m.directory)}/.agents-plugin/plugin.json<br>初始化入口：${esc(m.initSkill||'按 owner 接入说明检查')}</small>`);return}
if(op==='plugin'){if(isBase(arg)){toast('框架基础能力不参与启停');return}if(s.plugins[arg]){const dependents=catalog.filter(([k])=>k!==arg&&s.plugins[k]&&dependencies(k).includes(arg));modal('停用影响',dependents.length?`<p class="note warn">${dependents.map(x=>esc(x[1])).join('、')} 仍依赖此插件，当前不能停用。先处理依赖它的能力。</p>`:'<p>仅停用当前工程，不删除连接与共享物料。未发现已启用的反向依赖。</p>',dependents.length?'':btn('确认停用',`disable:${arg}`,true))}else{const needed=dependencies(arg).filter(k=>!isBase(k));modal('接入能力',`<h3>${esc(meta(arg).displayName||arg)}</h3><p class="note">将准备：${needed.map(k=>esc(meta(k)?.displayName||k)).join('、')}。补装不等于启用；配置与依赖检查完成后再启用。</p>`,btn('模拟补装并配置',`install:${arg}`,true))}return}
if(op==='disable'){if(isBase(arg))return;s.plugins[arg]=false;task(id,'停用 '+meta(arg).name+'（保留配置）','工具执行','已完成');save();$('#dialog').close();render();return}
if(op==='install'){if(isBase(arg))return;s.pendingPlugin=arg;s.available=[...new Set([...(s.available||[]),...dependencies(arg)])];task(id,'补装 '+meta(arg).name+' 及必需依赖','工具执行','已完成');save();$('#dialog').close();const t=task(id,'配置并初始化 '+(meta(arg).displayName||arg),'提示词交接','待接续');t.plugin=arg;t.required=dependencies(arg);t.entry=meta(arg).initSkill?`plugins/${meta(arg).directory}/skills/${meta(arg).initSkill}/SKILL.md`:`plugins/${meta(arg).directory}/AGENTS.md`;save();go('tasks');setTimeout(()=>showTask(t),50);return}
if(op==='adapt'){s.clients[arg]='入口已生成，宿主待发现';s.client=arg;save();render();toast('模拟入口已生成；不代表宿主已发现');return}
if(op==='discover'){if(!s.clients[arg]){toast('请先适配工程入口');return}s.clients[arg]='模拟宿主已发现，调用待验证';save();render();return}
if(op==='client-task'){s.client=arg;save();newAgent();return}if(op==='user-scope'){modal('用户级配置影响','<p>此类配置可能被其他工程共享。本原型仅展示范围，不修改客户端设置；正式实现优先使用工程级入口。</p>');return}
if(op==='secret'){modal('演示凭据',`<p>不收集真实密码。仅演示保留、替换、清除的意图。</p><div class="actions">${btn('保留现状','close')}${btn('替换为虚构凭据','secret-set')}${btn('明确清除','secret-clear')}</div>`);return}
if(op==='secret-set'||op==='secret-clear'){connectionFor(s).secret=op==='secret-set';s.tested=false;s.needsReconnect=true;save();$('#dialog').close();render();return}
if(op==='test-connection'){s.tested=true;s.needsReconnect=false;task(id,'检查演示连接','工具执行','已完成');save();render();toast('模拟检查通过，未发生真实网络访问');return}
if(op==='update'){if(projects[id].parent){modal('此操作影响共享框架','<p>本模块配置独立。共享框架更新需查看所有模块影响。</p>',btn('前往 Root 预览','root-update',true));return}modal('更新影响预览',`<p>目标：${esc(currentName())}。保留现有连接、显式禁用和自定义内容。</p><p class="note">${id==='root'?'共享物料只更新一次，再刷新口腔与护理模块。此演示将展示护理模块失败。':'此演示只更新当前工程。'}不会执行真实 Git 操作。</p>`,btn('模拟应用更新','apply-update',true));return}
if(op==='root-update'){$('#dialog').close();go('modules','root');setTimeout(()=>action('update'),60);return}
if(op==='apply-update'){s.updated=true;s.legacy=false;if(id==='root'){state('dental').updated=true;state('nursing').updated=false;const t=task(id,'共享框架更新与模块刷新','共享更新','部分完成');save();$('#dialog').close();go('tasks');setTimeout(()=>showTask(t),60)}else{task(id,'更新当前工程框架','工具执行','已完成');save();$('#dialog').close();render()}return}
if(op==='retry'){state('nursing').updated=true;findTask(arg).status='已完成';save();showTaskReplace(findTask(arg));render();return}
if(op==='task'){showTask(findTask(arg));return}if(op==='dispatch'){const t=findTask(arg);t.status='待补充回答';save();showTaskReplace(t);render();return}
if(op==='answer'){const value=$('#answer').value.trim();if(!value){toast('请先填写任务范围');$('#answer').focus();return}const t=findTask(arg);t.answer=value;t.status='等待 Agent 返回';save();showTaskReplace(t);render();return}
if(op==='copy'){try{await navigator.clipboard.writeText(prompt(id,findTask(arg)));toast('已复制；等待客户端执行后返回检查')}catch{toast('剪贴板不可用，请选中文本手动复制')}return}
if(op==='returned'){const t=findTask(arg);t.returned=true;t.status='结果待验证';save();showTaskReplace(t);render();return}
if(op==='verify'){const t=findTask(arg);if(!t.returned){toast('尚无返回结果：先完成宿主/人工步骤，再返回检查');return}t.status='已完成';if(s.pendingPlugin&&t.plugin===s.pendingPlugin){for(const k of t.required||[t.plugin])s.plugins[k]=true;delete s.pendingPlugin}save();showTaskReplace(t);render();toast('演示读回一致，任务完成；真实业务未验证');return}
if(op==='vector-preview'){modal('向量构建预览','<p>范围：三份演示手册。提供方：模拟服务；费用：未知。本原型不会外发。</p>',btn('模拟构建并中断','vector-build',true));return}
if(op==='vector-build'){s.vector=45;task(id,'向量构建','工具执行','已中断，可续建');save();$('#dialog').close();render();return}
if(op==='vector-resume'){s.vector=100;const t=s.tasks.find(t=>t.title==='向量构建');if(t)t.status='已完成';save();render();toast('模拟续建完成，已完成批次未重复');return}
if(op==='vector-export'){modal('导出摘要','<p>演示索引已完整，资料与模型匹配。正式导出由原框架校验，本原型不生成向量文件。</p>');return}
if(op==='doc'){manual=Number(arg);docText='';if(page!=='manual')go('manual');else{render();loadDoc()}return}
if(op==='manual-task'){newAgent(`按${docNames[manual]}核对当前工程`);return}
if(op==='confirm-config'){const draft=s.draft;if(!draft)return;if(s.conflict){modal('配置发生外部变化',`<p>基线端口：${connectionFor(s).port}；文件当前值（模拟）：57773；候选：${draft.port}。</p><p class="note warn">未写入候选。重新读取后再编辑，或交接 Agent 分析；不直接覆盖。</p>`,btn('重新读取并保留草稿','reload-config',true)+btn('生成冲突分析请求','diagnose'));return}s.name=draft.name;s.mode=draft.mode;connectionFor(s).host=draft.host;connectionFor(s).port=draft.port;s.tested=false;s.needsReconnect=true;delete s.draft;save();$('#dialog').close();task(id,'保存工程配置并读回','工具执行','已完成');if(s.pendingPlugin)newAgent('完成新增能力的初始化与检查');else render();toast('演示配置已保存，只影响当前工程');return}
if(op==='reload-config'){connectionFor(s).port=57773;s.tested=false;s.needsReconnect=true;s.conflict=false;save();$('#dialog').close();render();toast('已读取模拟外部值；原候选保留在草稿，可重新编辑提交');return}
}
function showTaskReplace(t){$('#dialog').close();showTask(t)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b)action(b.dataset.action)});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,s=state(id),v=new FormData(f);if(f.id==='purpose'){s.client=v.get('client');s.purpose=$('#purpose-select').value;s.wizard=2;save();render()}if(f.id==='config-form'){const port=Number(v.get('port')),name=String(v.get('name')).trim(),host=String(v.get('host')).trim();if(!name||!host||!Number.isInteger(port)||port<1||port>65535){toast('名称、地址不能为空，端口需为 1–65535 整数');return}const d={name,host,port,mode:v.get('mode')};if(f.dataset.wizard==='true'){s.name=d.name;s.mode=d.mode;Object.assign(connectionFor(s),{host,port});s.wizard=4;save();render()}else{s.draft=d;save();modal('确认配置影响',`<p>工程：${esc(currentName())}</p>${row('连接地址',`${esc(connectionFor(s).host)} → ${esc(host)}`)}${row('端口',`${connectionFor(s).port} → ${port}`)}<p class="note">仅当前工程；其他字段和凭据保持。</p>`,btn('应用并检查','confirm-config',true))}}if(f.id==='knowledge-search'){const q=String(v.get('query')).trim();$('#results').innerHTML=`<div class="note">${q?`“${esc(q)}”的演示检索结果：连接配置与排查 · docs/guides/connection-configuration.md`:'输入关键词查看本地来源。'} ${btn('打开来源','doc:1')}</div>`}});
document.addEventListener('input',e=>{if(e.target.id==='plugin-search'){const pos=e.target.selectionStart;filter=e.target.value;render();$('#plugin-search').focus();$('#plugin-search').setSelectionRange(pos,pos)}if(e.target.id==='manual-search'){const q=e.target.value.trim();$('#manual-match').textContent=q?(docText.includes(q)||docNames.some(n=>n.includes(q))?'当前手册或标题中有匹配':'当前内容未找到匹配'):'输入关键词检索'}});
document.addEventListener('change',e=>{if(e.target.id==='plugin-group'){group=e.target.value;render()}});
addEventListener('hashchange',route);route();
